    'finance_policies_simulator_t1' => 'প্রতিটি নিয়ম বদল ও তার তারিখের একটি তালিকা রাখুন।',
    'finance_policies_simulator_t2' => 'ডিলার ও সাব-ডিলার—দুই দামেই পরীক্ষা করুন।',
    'finance_policies_simulator_title' => 'কমিশন নিয়ম ও পরীক্ষামূলক ক্যালকুলেটর',
    'finance_policies_simulator_w1' => 'ক্যালকুলেটরের ফলাফল দেখে কাউকে টাকা দেবেন না।',
    'finance_policies_simulator_w2' => 'নতুন নিয়মের সাথে “মেলাতে” পুরনো সেভ করা ভাগ বদলাবেন না।',
    'finance_policies_simulator_why' => 'আগে পরীক্ষা না করে চালু নিয়মে পরীক্ষা করলে হিসাব খাতায় এমন ভুল এন্ট্রি থেকে যায় যা আর মোছা যায় না।',
    'finance_treasury_badge' => 'ট্রেজারি',
    'finance_treasury_title' => 'ট্রেজারি: কোম্পানির সব ফান্ড এক জায়গায়',
    'finance_treasury_summary' => 'প্রতিটি ফান্ডে আছে কত এসেছে, কত বের হয়েছে আর এখন কত আছে।',
    'finance_treasury_purpose' => 'কোম্পানির টাকার একটাই জায়গা ট্রেজারি। এর ট্যাব: ফান্ড, অর্ডারের হিসাব, সব ঘটনা, পার্টনারদের টাকা, টাকার কাজ।',
    'finance_treasury_why' => 'এক জায়গায় থাকলে এক পাতার সাথে আরেক পাতা মেলাতে হয় না।',
    'finance_treasury_s1' => 'মেনু থেকে ট্রেজারি খুলুন। “ফান্ড” ট্যাবে প্রতিটি ফান্ডের একটি করে কার্ড আছে।',
    'finance_treasury_s2' => 'কোনো ফান্ডে চাপলে কত এসেছে আর কত বের হয়েছে তা দেখবেন, ওপরে একই তিনটি হিসাব থাকবে।',
    'finance_treasury_s3' => 'ফান্ড থেকে খরচ করতে ফান্ডটি খুলে “খরচ করুন” চাপুন। স্টাফ খরচ লিখলে টাকার কাজ পাতায় অন্য একজন অনুমোদন করবেন। মালিক যেকোনো খরচ অনুমোদন করতে পারেন, নিজের লেখা খরচও।',
    'finance_treasury_s4' => '“সব ঘটনা” পাতায় অর্ডার, টাকা জমা, কমিশন, টাকা তোলা, স্টক আসা-যাওয়া সব সময় ধরে আছে। ফিল্টার করে যেকোনো একটি দেখুন।',
    'finance_treasury_s5' => '“পার্টনারদের টাকা” পাতায় প্রতিটি ডিলার ও সাব-ডিলারের এখনকার টাকা আর এখন পর্যন্ত মোট হিসাব আছে।',
    'finance_treasury_s6' => '“টাকার কাজ” পাতায় যা কিছু কারও কাজের অপেক্ষায় সব আছে: টাকা যাচাই, টাকা তোলা, মাসের হিসাব, আটকে থাকা কমিশন ইত্যাদি।',
    'finance_treasury_o1' => 'প্রতিটি হিসাবের পেছনের লাইনগুলো খুলে দেখা যায়।',
    'finance_treasury_t1' => 'কার্ডে সবসময় আজ পর্যন্ত মোট হিসাব থাকে, তারিখ বদলালে শুধু তালিকা বদলায়।',
    'finance_treasury_w1' => 'এই পাতার ছবি পার্টনারদের গ্রুপে দেবেন না।',
    'financial_activation_gates_badge' => 'লাইভ টাকার সুইচ',
    'financial_activation_gates_o1' => 'টাকার হিসাব লাইভ নাকি ট্রায়াল মোডে আছে, সবাই জানে।',
    'financial_activation_gates_o2' => 'আসল চালুর আগে লিখিত অনুমোদন ও সবকিছু প্রস্তুত থাকার প্রমাণ থাকে।',
    'financial_activation_gates_o3' => 'সাপোর্ট স্টাফ টাকার হিসাব কেন বন্ধ তা বুঝিয়ে বলতে পারেন, নিজে থেকে চালুর তারিখ বানিয়ে বলেন না।',
    'financial_activation_gates_purpose' => 'মদিনা “সফটওয়্যার প্রস্তুত” আর “ব্যবসা আসলে চালু”—এই দুটো আলাদা রাখে। ট্রায়াল মোড ও লাইভ টাকার সুইচ আসল টাকা সুরক্ষিত রাখে।',
    'financial_activation_gates_s1' => 'দুটি সুইচ চিনে নিন: ট্রায়াল মোড ও লাইভ টাকার হিসাব (আর আলাদা অটো-রিলিজ সেটিং)।',
    'financial_activation_gates_s2' => 'লাইভ টাকার হিসাব বন্ধ থাকলেও ক্যালকুলেটর ও ডিলারদের অনেক পাতা চলে, কিন্তু আসল কোনো পাওনা বা আয় তৈরি হয় না।',
    'financial_activation_gates_s3' => 'চালুর সিদ্ধান্ত নেওয়ার আগে দেখে নিন সিস্টেম প্রস্তুত কি না।',
    'financial_activation_gates_s4' => 'হিসাব বিভাগে দ্বিতীয় কেউ থাকলে শুরুর ব্যালেন্স ও কমিশনের নিয়ম তাঁকে দিয়ে যাচাই করান। আগের কোনো ব্যালেন্স না থাকলে মালিক "নতুন শুরু" বেছে নিতে পারেন।',
    'financial_activation_gates_s5' => 'লাইভ টাকার হিসাব শুধু নিয়ন্ত্রিত চালুর সেটিং থেকেই চালু করুন, তাড়াহুড়ো করে সার্ভারে বদল করে নয়।',
    'financial_activation_gates_s6' => 'সঠিক তারিখ ও সময় দিয়ে সার্কুলারের মাধ্যমে ডিলারদের চালুর খবর দিন।',
    'financial_activation_gates_s7' => 'প্রথম দিন হিসাব খাতা ও পেমেন্টের দিকে বিশেষ নজর রাখুন।',
    'financial_activation_gates_s8' => 'লাইভ টাকার হিসাব থামাতে হলে কী করবেন, তার পরিকল্পনা আগেই রাখুন।',
    'financial_activation_gates_summary' => 'টাকার হিসাব কেন বন্ধ থাকতে পারে এবং চালুর আগে মালিককে কী যাচাই করতে হবে, বুঝুন।',
    'financial_activation_gates_t1' => 'শেয়ার করা ডেমো সিস্টেমে লাইভ টাকার হিসাব বন্ধ রাখুন।',
    'financial_activation_gates_t2' => 'সাপোর্ট স্টাফকে শেখান কীভাবে তারিখের কথা না দিয়ে সুইচের বিষয়টি বোঝাতে হয়।',
    'financial_activation_gates_t3' => 'লাইভ টাকার হিসাব চালু করার সময় ব্যাকআপ ঠিক আছে কিনা দেখুন।',
    'financial_activation_gates_title' => 'লাইভ টাকার হিসাব, ট্রায়াল মোড ও আসল চালু',
    'financial_activation_gates_w1' => 'তথ্য অসম্পূর্ণ থাকলে শুধু “খালি ব্যালেন্স ঠিক করতে” লাইভ টাকার হিসাব চালু করবেন না।',
    'financial_activation_gates_w2' => 'আসল ব্যবসার সিস্টেমে কখনো ডেমো তথ্য চালাবেন না।',
    'financial_activation_gates_w3' => 'অটো-রিলিজ একটি আলাদা সুইচ। এটি নিজে থেকে চালু হয় না।',
    'financial_activation_gates_why' => 'শুরুর ব্যালেন্স অসম্পূর্ণ রেখে তাড়াতাড়ি টাকার হিসাব চালু করলে এমন ভুল আয় তৈরি হতে পারে যা আর ফেরানো যায় না।',
    'getting_started_badge' => 'শুরু করুন',
    'getting_started_o1' => 'আপনি সঠিক প্যানেলে লগইন করেছেন এবং আপনার পদের জন্য অনুমোদিত অংশগুলো দেখছেন।',
    'getting_started_o2' => 'লাইভ গাইড ট্যুর আর খোঁজা যায় এমন এই ব্যবহার নির্দেশিকার পার্থক্য আপনি জানেন।',
    'getting_started_o3' => 'যে পাতায় আছেন সেখান থেকেই যেকোনো সময় সাহায্য খুলতে পারেন।',
    'getting_started_purpose' => 'এই অধ্যায় মালিক, স্টাফ, ডিলার ও সাব-ডিলার—সবাইকে নিরাপদে সঠিক প্যানেলে লগইন করতে এবং প্রতিদিনের কাজের জন্য প্রস্তুত হতে সাহায্য করে।',
    'getting_started_s1' => 'আপনার লগইন পাতা চিনে নিন: মালিক — sadmin, স্টাফ — manage, ডিলার — dealer, সাব-ডিলার — subdealer। পাবলিক ওয়েবসাইট শুধু দেখার জন্য।',
    'getting_started_s10' => 'প্রথম লগইনের পর টাকা তোলা বা বড় অর্ডারের মতো কাজ করার আগে প্রোফাইল ও নিরাপত্তার তথ্য হালনাগাদ করুন।',
    'getting_started_s2' => 'আপনার প্যানেলের লগইন পাতা খুলে ইমেইল বা ফোন (ডিলার ও সাব-ডিলাররা ডিলার কোডও দিতে পারেন) ও পাসওয়ার্ড দিয়ে লগইন করুন।',
    'getting_started_s3' => 'OTP বা দুই ধাপের লগইন (2FA) চালু থাকলে ড্যাশবোর্ড খোলার আগে কোডটি দিন।',
    'getting_started_s4' => 'প্রথম লগইনে লাইভ গাইড ট্যুর এলে তা শেষ করুন। এটি শুধু ড্যাশবোর্ডের প্রধান বাটনগুলো দেখায়। এই লিখিত নির্দেশিকা আলাদা এবং এতে আরও বিস্তারিত আছে।',
    'getting_started_s5' => 'ওপরের বারে আপনার নাম, পদ, ভাষা বদলের বাটন ও দিন/রাত বাটন আছে কিনা দেখুন। শুরুতে দিনের (হালকা) মোড চালু থাকে।',
    'getting_started_s6' => 'ড্যাশবোর্ডের সংখ্যা দেখুন: অর্ডার, ডেলিভারি, আয় ও আপনার টাকা, এবং আগের ধাপ শেষ করতে বলা কোনো ব্যানার থাকলে সেটি।',
    'getting_started_s7' => 'যেকোনো সময় ওপরের কম্পাসে চাপ দিয়ে অধ্যায় খুঁজুন বা ড্যাশবোর্ড ট্যুর আবার চালান (ফোনে এটি আপনার ছবির নিচের মেনুতে আছে)। ডিলার ও সাব-ডিলাররা অফিসে যোগাযোগ → সাহায্য থেকে সাহায্যের অনুরোধ পাঠাতে পারেন।',
    'getting_started_s8' => 'শুধু নিজের প্যানেলের ঠিকানা বুকমার্ক করুন। লগইন পাতায় অন্য প্যানেলের লিংক শুধু তথ্যের জন্য। মালিকের পাসওয়ার্ড কখনো স্টাফ (Manage) প্যানেলে ব্যবহার করবেন না।',
    'getting_started_s9' => 'লগইন না হলে প্যানেলের ঠিকানা, লগইন তথ্য, অ্যাকাউন্ট চালু নাকি স্থগিত, এবং স্টাফ অনুমতি যুক্ত করা লাগবে কিনা দেখুন।',
    'getting_started_summary' => 'আপনার পদ অনুযায়ী সঠিকভাবে লগইন করুন, ড্যাশবোর্ড চিনে নিন এবং সাহায্য ও সাপোর্ট কোথায় আছে জানুন।',
    'getting_started_t1' => 'ভাষা বদলের বাটন থেকে বাংলা বা English বেছে নিন; আপনার পছন্দ সেভ থাকবে।',
    'getting_started_t2' => 'লাইভ ট্যুর বাদ দিয়ে থাকলে সাহায্য পাতা থেকে আবার চালু করুন। ট্যুর ইচ্ছা করেই এই নির্দেশিকার চেয়ে ছোট রাখা হয়েছে।',
    'getting_started_t3' => 'লাইভ টাকার হিসাব কবে চালু হবে, তা শুধু মালিক ও হিসাব বিভাগ ঠিক করে। কোম্পানি প্রস্তুত না হওয়া পর্যন্ত ডিলাররা এটি আশা করবেন না।',
    'getting_started_title' => 'মদিনা প্যানেলে শুরু করুন',
    'getting_started_w1' => 'আপনার OTP, অ্যাপ কোড বা পাসওয়ার্ড কাউকে দেবেন না, কোনো স্টাফ এমনি জিজ্ঞেস করলেও না।',
    'getting_started_w2' => 'চালু (লাইভ) সিস্টেমে কখনো ডেমো বা পরীক্ষার তথ্য চালাবেন না।',
