    'website_button_t1' => 'প্যানেল খোলা রাখতে চাইলে নতুন ব্রাউজার ট্যাবে ওয়েবসাইট খুলুন।',
    'website_button_w1' => 'ওয়েবসাইটে গেলে লগআউট হয় না। অন্যের কম্পিউটারে কাজ শেষে লগআউট করে নিন।',

    'prescriptions_partner_badge' => 'প্রেসক্রিপশন',
    'prescriptions_partner_title' => 'ডিলার ও সাব-ডিলারের প্রেসক্রিপশন',
    'prescriptions_partner_summary' => 'আপনার রেজিস্ট্রেশন যাচাই হলে রোগীর তথ্য রাখতে আর প্রেসক্রিপশন লিখতে পারবেন।',
    'prescriptions_partner_purpose' => 'শুরুতে সব ডিলার ও সাব-ডিলারের প্রেসক্রিপশন বন্ধ থাকে। রেজিস্ট্রেশন যাচাই করে প্রেসক্রিপশন চালু করার পরই মেনুতে এটি আসে।',
    'prescriptions_partner_why' => 'প্রেসক্রিপশন একটি চিকিৎসার কাগজ। যাচাই করা রেজিস্ট্রেশন যার আছে, শুধু তিনিই এটি লিখবেন।',
    'prescriptions_partner_s1' => 'আপনার রেজিস্ট্রেশনের কাগজ (বিএমডিসি, ইউনানি বোর্ড বা আয়ুর্বেদিক বোর্ড) মালিক বা অফিসকে দেখান। তারা যাচাই করে প্রেসক্রিপশন চালু করবেন।',
    'prescriptions_partner_s2' => 'তারপর মেনু থেকে “প্রেসক্রিপশন” খুলুন।',
    'prescriptions_partner_s3' => '“প্রেসক্রিপশন” ট্যাবে “নতুন প্রেসক্রিপশন” অংশে আগে বলুন কার জন্য লিখছেন। “পুরোনো রোগী” চাপলে তালিকা থেকে রোগী বেছে নিন; তালিকা খুললে ওপরের ঘরে নাম লিখে খোঁজা যায়।',
    'prescriptions_partner_s4' => 'রোগী নতুন হলে “নতুন রোগী” চেপে নাম ও অন্য তথ্য লিখুন, সম্মতির ঘরে টিক দিন, তারপর “এগিয়ে যান” চাপুন। রোগীর তথ্য প্রেসক্রিপশনের সাথেই সেভ হয়; আলাদা করে সেভ করতে হয় না।',
    'prescriptions_partner_s5' => 'প্রতিটি ওষুধ কোম্পানির তালিকা থেকে বেছে নিন। মালিক অন্য কোম্পানির ওষুধ চালু রাখলে "অন্য ওষুধ" চেপে নাম আর শক্তি হাতে লেখা যায়। মাত্রা, দিনে কতবার আর কত দিন লিখুন। তারপর দাম, পরিমাণ আর ছাড় থাকলে তা লিখুন। নিচের ঘরে টেস্ট, যা খাবেন, যা খাবেন না আর পরামর্শ লেখা যায়।',
    'prescriptions_partner_s6' => 'আরেকটি ওষুধ লিখতে “ওষুধ যোগ করুন” চাপুন। ওষুধ ছাড়া শুধু টেস্ট বা পরামর্শও দেওয়া যায়। সব দেখে “প্রেসক্রিপশন সেভ করুন” চাপুন।',
    'prescriptions_partner_s7' => 'প্রিন্ট করতে “প্রিন্ট (বাংলা)” বা “প্রিন্ট (ইংরেজি)” চাপুন।',
    'prescriptions_partner_o1' => 'আপনার রোগী আর প্রেসক্রিপশন শুধু আপনিই দেখতে পান। মালিকও দেখতে পান না।',
    'prescriptions_partner_o2' => 'আপনার দেওয়া দাম, পরিমাণ আর ছাড় থেকে মোট টাকা হিসাব হয়।',
    'prescriptions_partner_t1' => 'একটি প্রেসক্রিপশনে সর্বোচ্চ ৩০টি ওষুধ লেখা যায়।',
    'prescriptions_partner_t2' => 'আপনার রেজিস্ট্রেশন নম্বর প্রেসক্রিপশনে ছাপা হয়।',
    'prescriptions_partner_w1' => 'এই ওষুধগুলো আপনি নিজে লেখেন, কোম্পানির স্টক থেকে যায় না। এগুলো কোম্পানির অর্ডার নয়, এতে কোনো কমিশনও নেই।',

    'prescriptions_verify_badge' => 'প্রেসক্রিপশন',
