    'prescriptions_verify_summary' => 'মালিক, অথবা “প্রেসক্রাইবার যাচাই” অনুমতি পাওয়া স্টাফ রেজিস্ট্রেশন দেখে প্রেসক্রিপশন চালু করেন।',
    'prescriptions_verify_purpose' => 'সব ডিলার ও সাব-ডিলারের প্রেসক্রিপশন শুরুতে বন্ধ থাকে। কেউ কাগজ দেখে চালু না করা পর্যন্ত বন্ধই থাকে।',
    'prescriptions_verify_why' => 'যাদের আসল রেজিস্ট্রেশন আছে, শুধু তারাই প্রেসক্রিপশন লিখবেন। প্রতিটি পরিবর্তন “কাজের রেকর্ড”-এ লেখা থাকে।',
    'prescriptions_verify_s1' => 'পার্টনারের রেজিস্ট্রেশনের কাগজ নিজে দেখে যাচাই করুন।',
    'prescriptions_verify_s2' => '“ডিলার” বা “সাব-ডিলার” তালিকায় পার্টনারকে খুঁজে “এডিট / অবস্থা” চাপুন।',
    'prescriptions_verify_s3' => '“প্রেসক্রিপশন” অংশে রেজিস্ট্রেশনের ধরন বেছে নিন: বিএমডিসি (অ্যালোপ্যাথিক), ইউনানি বোর্ড বা আয়ুর্বেদিক বোর্ড।',
    'prescriptions_verify_s4' => 'রেজিস্ট্রেশন নম্বর লিখুন, চাইলে নোট দিন, তারপর “প্রেসক্রিপশন চালু করুন” চাপুন।',
    'prescriptions_verify_s5' => 'এরপর পার্টনার মেনুতে “প্রেসক্রিপশন” দেখতে পাবেন।',
    'prescriptions_verify_s6' => 'বন্ধ করতে চাইলে কারণ লিখতে পারেন, তারপর “বন্ধ করুন” চাপুন।',
    'prescriptions_verify_o1' => 'এই অংশে দেখা যায় কে কখন চালু বা বন্ধ করেছেন।',
    'prescriptions_verify_t1' => 'মালিক: কোনো স্টাফকে এই কাজ দিতে “স্টাফ তালিকা” পাতায় তাকে “প্রেসক্রাইবার যাচাই” অনুমতি দিন।',
    'prescriptions_verify_w1' => 'কাগজ নিজে দেখার পরই চালু করুন।',

    'clinic_prescriptions_badge' => 'চেম্বার',
    'clinic_prescriptions_title' => 'মালিকের চেম্বারের প্রেসক্রিপশন',
    'clinic_prescriptions_summary' => 'মালিক কোম্পানির পণ্য দিয়ে প্রেসক্রিপশন লেখেন আর ব্রাঞ্চ থেকে ওষুধ দেন।',
    'clinic_prescriptions_purpose' => 'মালিক ওষুধ দিলে বেছে নেওয়া ব্রাঞ্চের স্টক কমে, আর টাকা দুই তহবিলে ভাগ হয়।',
    'clinic_prescriptions_why' => 'প্রতিটি প্রেসক্রিপশনে প্রস্তুতকারকের ভাগ আর চেম্বারের ভাগ লেখা থাকে, তাই হিসাব পরিষ্কার থাকে।',
    'clinic_prescriptions_s1' => 'মেনু থেকে “প্রেসক্রিপশন” খুলুন। সুপার অ্যাডমিন লগইনে এই পাতা সবসময় থাকে। অফিসের অন্য অ্যাকাউন্টে থাকে শুধু সেই অ্যাকাউন্টের জন্য চালু করা হলে।',
    'clinic_prescriptions_s2' => 'প্রথমবার “সেটিংস” ট্যাবে গিয়ে আপনার রেজিস্ট্রেশনের ধরন ও নম্বর সেভ করুন। এগুলো আপনার প্রেসক্রিপশনে ছাপা হয়।',
    'clinic_prescriptions_s3' => '“প্রেসক্রিপশন” ট্যাবে “নতুন প্রেসক্রিপশন” অংশে আগে বলুন কার জন্য লিখছেন: “পুরোনো রোগী” চেপে তালিকা থেকে বেছে নিন, অথবা “নতুন রোগী” চেপে নাম ও তথ্য লিখে “এগিয়ে যান” চাপুন। নতুন রোগী প্রেসক্রিপশনের সাথেই সেভ হয়।',
    'clinic_prescriptions_s4' => 'প্রতিটি লাইনে কোম্পানির পণ্য বেছে নিন; তালিকা খুললে ওপরের ঘরে নাম লিখে খোঁজা যায়। নাম আর এমআরপি পণ্য থেকে আসে। আপনার দাম, পরিমাণ আর ছাড় থাকলে তা লিখুন। নিচের ঘরে টেস্ট, যা খাবেন, যা খাবেন না আর পরামর্শ লেখা যায়।',
    'clinic_prescriptions_s5' => '“প্রেসক্রিপশন সেভ করুন” চাপুন। অবস্থা দেখাবে “লেখা হয়েছে”।',
    'clinic_prescriptions_s6' => 'তালিকায় ব্রাঞ্চ বেছে “ওষুধ দিন” চাপুন, তারপর নিশ্চিত করুন। ওই ব্রাঞ্চের স্টক কমবে আর অবস্থা দেখাবে “ওষুধ দেওয়া হয়েছে”।',
    'clinic_prescriptions_s7' => 'যেকোনো তারিখের বিক্রি, প্রস্তুতকারক তহবিল আর চেম্বার তহবিল দেখতে “চেম্বারের হিসাব” ট্যাব খুলুন।',
    'clinic_prescriptions_o1' => 'প্রতিটি পণ্যের এমআরপির ৩০% যায় প্রস্তুতকারক তহবিলে।',
    'clinic_prescriptions_o2' => 'আপনার দামের বাকি টাকা যায় চেম্বার তহবিলে।',
    'clinic_prescriptions_o3' => 'এতে কোনো ডিলার অর্ডার হয় না, ডিলারের কমিশনও হয় না।',
    'clinic_prescriptions_t1' => 'উদাহরণ: এমআরপি ৳১০০ আর আপনার দাম ৳৭০। ৳৩০ যায় প্রস্তুতকারক তহবিলে, ৳৪০ যায় চেম্বার তহবিলে।',
    'clinic_prescriptions_t2' => 'প্রত্যেক প্রেসক্রাইবার শুধু নিজের রোগী ও প্রেসক্রিপশন দেখেন। আপনি কোনো পার্টনারের রোগী দেখতে পারবেন না, আর ওষুধ দিতে পারবেন শুধু নিজের চেম্বারের প্রেসক্রিপশনে।',
    'clinic_prescriptions_w1' => 'এমআরপির ৩০%-এর কম দাম আটকে যায়, যদি না “সেটিংস”-এ বদলান। চলতে দিলে চেম্বার তহবিল শূন্যের নিচে যায়।',

    // এই ফিচারগুলোর প্রথম লগইনের ট্যুর ধাপ (TourGuide পড়ে)।
